	'egress.heavy_ok':    '그래도 보내기',
	'egress.reach_title': '{host}에 닿을까요?',
	'egress.reach_body':  '이번 턴은 작업 공간 밖의 웹 페이지나 메시지를 읽었고, 그 안의 무언가가 Daimond을 조종하고 있을 수도 있어요.\n\n이제 전에 가 본 적 없는 {host}에 닿으려고 해요. 알고 있는 무엇이든 그 주소에 실릴 수 있어요.\n\n예상한 일일 때만 허용하세요.',
	'egress.reach_ok':    '{host} 허용',
	'egress.any_title':  '어떤 웹사이트든 닿아도 될까요?',
	'egress.any_body':   '이 대화는 다른 사람이 쓴 웹 페이지나 메시지를 읽었고, 그 안의 무언가가 Daimond을 조종하고 있을 수도 있어요.\n\n지금은 {host}에 닿으려고 해요.\n\n예라고 하면 이 대화가 이어지는 동안 이 사이트뿐 아니라 어떤 웹사이트에도 닿을 수 있고, 여기서 다시 묻지 않아요. Daimond이 아는 것은 무엇이든 웹 주소에 적어 넣을 수 있으니, 닿은 페이지가 당신의 말을 가져갈 수 있어요.\n\n새 채팅에서는 다시 묻고, 새 다이몬도 마찬가지예요. 유난히 긴 주소는 지금 무엇이라 답하든 늘 따로 여쭤봐요.',
	'egress.any_ok':     '여기서는 모든 사이트 허용',
